using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.NTF.TiposNotificacion;using GraphApi.Services.NTF.TiposNotificacion;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.NTF.TiposNotificacion{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposNotificacions: creación, actualización y eliminación.")]    public class TiposNotificacionMutation    {        [Authorize]        [GraphQLName("createTiposNotificacion")]        [GraphQLDescription("Crea un nuevo TiposNotificacion usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposNotificacion> CreateTiposNotificacionAsync(            [GraphQLDescription("Datos necesarios para crear el TiposNotificacion.")]            clCreateTiposNotificacion objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposNotificacion.")]            ITiposNotificacionService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposNotificacion(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposNotificacion")]        [GraphQLDescription("Actualiza los campos especificados de un TiposNotificacion existente.")]        public async Task<clReadTiposNotificacion?> UpdateTiposNotificacionAsync(            [GraphQLDescription("Datos del TiposNotificacion a actualizar.")]            clUpdateTiposNotificacion objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposNotificacion.")]            ITiposNotificacionService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposNotificacion(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposNotificacion")]        [GraphQLDescription("Elimina un TiposNotificacion por su ID.")]        public async Task<bool> delTiposNotificacionAsync(            [GraphQLDescription("ID del TiposNotificacion a eliminar.")]            int nTiposNotificacionID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposNotificacion.")]            ITiposNotificacionService objService        )        {            return await objService.DeleteTiposNotificacion(nTiposNotificacionID);        }    }}